		/** 
		 * Tests creating a new Account.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Account");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Account" );

			try {            
				Account entity = AccountService.getAccountInstance().createAccount( generateNewEntity() );
				thePrimaryKey = entity.getAccountId();
				LOGGER.info( "-- Successfully created a Account with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Account. 
		 */
		public Account testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Account" );

			Account entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Account with primary key" );
			msg.append( thePrimaryKey );
			
			AccountFetchOneSummary fetchOneSummary = new AccountFetchOneSummary( thePrimaryKey );

			try {
				entity = AccountService.getAccountInstance().getAccount( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Account " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Account.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Account." );

			StringBuilder msg = new StringBuilder( "Failed to update a Account : " );        
			Account entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Account." );

				// for use later on...
				thePrimaryKey = entity.getAccountId();

				AccountService proxy = AccountService.getAccountInstance();            
				proxy.updateAccount( entity );   

				LOGGER.info( "-- Successfully saved Account - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Account.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Account." );

			try{
			    Account entity = testRead(); 
				AccountService.getAccountInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Account with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Account with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Accounts.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Accounts:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Account : " );        
			List<Account> collection  = null;

			try {
				// call the static get method on the AccountService
				collection = AccountService.getAccountInstance().getAllAccount();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Account entity = null;            
					Iterator<Account> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getAccountId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

