		protected Account generateNewEntity() {
			Account entity = new Account( null,  new AccountNumber(),  new IBAN(),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),   new Date(),   new Date(),  null,  null,  null,  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  new HashSet<>(),  AccountType.values()[0],  AccountOwnershipType.values()[0],  AccountStatus.values()[0] );
			
			return( entity );
		}

